package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaElDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujood)", "(Ο Αλλάχ είναι) Δοξασμένος, Πανάγιος, Κύριος των αγγέλων και του Πνεύματος (Τζιμπρίλ).", "Σε ρούκου και σουτζούντ.", "Ο Προφήτης ﷺ το απήγγειλε αυτό σε ρούκου και σουτζούντ."),
        "dua_sujood_dhanbi_kullah" to DuaText("Στο Sujood: Forgive All My Sins", "Ω Αλλάχ, συγχώρεσε με όλες τις αμαρτίες μου - τις μικρές και τις μεγάλες, τις πρώτες και τις τελευταίες, τις ανοιχτές και τις κρυφές.", "Στο sujood.", "Η υπόκλιση είναι ένα μέρος όπου απαντώνται οι ντουές."),
        "dua_sujood_ridaka" to DuaText("Καταφύγιο στην ευχαρίστησή σας", "Ω Αλλάχ, αναζητώ καταφύγιο στην ευχαρίστησή Σου από τον θυμό Σου, στη συγγνώμη Σου από την τιμωρία Σου, και αναζητώ καταφύγιο σε Σένα από Σένα. Δεν μπορώ να Σε επαινέσω πλήρως. Είστε όπως έχετε επαινέσει τον εαυτό σας.", "Στο sujood — Η Aisha (RA) άκουσε τον Προφήτη ﷺ να το λέει αυτό.", "Ένα sujood dua του Προφήτη ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Όλες οι λεκτικές, σωματικές και οικονομικές πράξεις λατρείας είναι για τον Αλλάχ. Ειρήνη σε σένα, Προφήτη, και το έλεος του Αλλάχ και οι ευλογίες Του. Ειρήνη σε εμάς και στους δίκαιους υπηρέτες του Αλλάχ. Καταθέτω μαρτυρία ότι κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, και καταθέτω μαρτυρία ότι ο Μωάμεθ ﷺ είναι ο υπηρέτης και ο αγγελιοφόρος Του.", "Σε κάθε συνεδρίαση — αφηγείται ο Abdullah ibn Mas'ud (RA) (η πρακτική των Χανάφι).", "Ο Προφήτης ﷺ το δίδαξε σαν σούρα του Κορανίου."),
        "dua_sajdah_tilawah" to DuaText("Sajdah της απαγγελίας", "Το πρόσωπό μου έχει προσκυνήσει Εκείνον που το δημιούργησε και έφερε την ακοή και την όρασή του με τη δύναμη και τη δύναμή Του.", "Στην υπόκλιση της απαγγελίας.", "Ο Προφήτης ﷺ το είπε αυτό στην υπόκλιση της απαγγελίας τη νύχτα."),
        "dua_after_witr" to DuaText("Μετά το Witr", "Δόξα στον Βασιλιά, τον Πανάγιο.", "Τρεις φορές μετά το σαλάμ του βιτρ, υψώνοντας τη φωνή την τρίτη φορά.", "Ο Προφήτης ﷺ το είπε αυτό μετά το witr."),
        "dua_tahajjud_nur" to DuaText("Παράκληση έναρξης Tahajjud", "Ω Αλλάχ, σε Σένα ανήκει ο έπαινος. Είσαι ο Συντηρητής των ουρανών, της γης και όλων μέσα σε αυτά. Σε Σένα ανήκει ο έπαινος. Είσαι το Φως των ουρανών, της γης και όλων μέσα σε αυτά. Σε Σένα ανήκει ο έπαινος. Είσαι η Αλήθεια, η υπόσχεσή σου είναι αληθινή, η συνάντηση μαζί Σου είναι αληθινή, ο λόγος Σου είναι αληθινός, ο Παράδεισος είναι αληθινός, η Κόλαση είναι αληθινή, οι Προφήτες είναι αληθινοί, ο Μωάμεθ ﷺ είναι αληθινός και η Ώρα είναι αληθινή.", "Κατά την έναρξη της νυχτερινής προσευχής (tahajjud) (το εναρκτήριο μέρος της ντουά).", "Ο Προφήτης ﷺ το απήγγειλε αυτό όταν σηκώθηκε για tahajjud (η πλήρης ντουά είναι στο al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Οδηγήστε με σε αμφισβητούμενα θέματα", "Ω Αλλάχ, Κύριε του Τζιμπρίλ, του Μικαΐλ και του Ισραφίλ, Δημιουργός των ουρανών και της γης, Γνώστης του αόρατου και του ορατού! Θα κρίνεις ανάμεσα στους υπηρέτες Σου σε ό,τι διέφεραν. Καθοδήγησέ με με την άδειά Σου στην αλήθεια σε ό,τι έχει διαφωνήσει. Πράγματι, εσύ καθοδηγείς όποιον θέλεις σε μια ευθεία οδό.", "Στην αρχή του tahajjud — για καθοδήγηση στην αλήθεια εν μέσω διαφωνίας.", "Ο Προφήτης ﷺ ξεκίνησε τη νυχτερινή του προσευχή με αυτή τη ντουά."),
        "dua_going_to_mosque_nur" to DuaText("Πηγαίνοντας στο Τζαμί (Dua of Light)", "Ω Αλλάχ, βάλε φως στην καρδιά μου, φως στα μάτια μου, φως στα αυτιά μου, φως στα δεξιά μου, φως στα αριστερά μου, φως από πάνω μου, φως από κάτω μου, φως μπροστά μου, φως πίσω μου, και κάνε φως για μένα.", "Πηγαίνοντας στο τζαμί για το Fajr.", "Ο Προφήτης ﷺ το απήγγειλε αυτό όταν έβγαινε για προσευχή."),
        "dua_waswasa_salah" to DuaText("Waswasa κατά τη διάρκεια του Salah (Khinzab)", "Αναζητώ καταφύγιο στον Αλλάχ από τον Σαϊτάν, τον καταραμένο.", "Όταν έρχονται σατανικοί ψίθυροι κατά τη διάρκεια της προσευχής, αναζητήστε καταφύγιο και φτύστε ελαφρά προς τα αριστερά τρεις φορές.", "Ο Uthman ibn Abil-'As (RA) το έκανε αυτό και οι ψίθυροι έφυγαν."),
        "dua_alimal_ghayb" to DuaText("Γνωριστής του Αόρατου", "Ω Αλλάχ, γνώστης του αοράτου και του ορατού, Δημιουργός των ουρανών και της γης, Κύριε και Κυρίαρχε όλων των πραγμάτων! Δίνω μαρτυρία ότι δεν υπάρχει θεός εκτός από Εσένα. Αναζητώ καταφύγιο σε Σένα από το κακό του εαυτού μου και από το κακό του Σαϊτάν και το (κάλεσμά του) σιρκ.", "Πρωί, βράδυ και πριν από τον ύπνο — ο Προφήτης ﷺ το δίδαξε στον Αμπού Μπακρ (RA).", "Προστασία από το κακό του εαυτού και του Σαϊτάν."),
        "dua_fitratil_islam" to DuaText("Πάνω στο Fitrah του Ισλάμ", "Έχουμε μπει το πρωί στη φίτρα του Ισλάμ, στον λόγο της ειλικρίνειας, στη θρησκεία του Προφήτη μας Μωάμεθ ﷺ και στον τρόπο του πατέρα μας Ιμπραήμ (AS), ο οποίος ήταν όρθιος και μουσουλμάνος, και δεν ήταν από τους πολυθεϊστές.", "Το πρωί.", "Ανανεώνοντας την πίστη σου κάθε πρωί."),
        "dua_amsayna_fitrah" to DuaText("Βράδυ στη Φιτρά του Ισλάμ", "Έχουμε μπει το βράδυ στη φίτρα του Ισλάμ, στον λόγο της ειλικρίνειας, στη θρησκεία του Προφήτη μας Μωάμεθ ﷺ και στον τρόπο του πατέρα μας Ιμπραήμ (AS), ο οποίος ήταν όρθιος και μουσουλμάνος, και δεν ήταν από τους πολυθεϊστές.", "Το βράδυ.", "Ανανεώνοντας την πίστη σου κάθε απόγευμα."),
        "dua_tahleel_10_fajr" to DuaText("Δέκα Tahleel μετά το Fajr και το Maghrib", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο. Δική του είναι η κυριαρχία και δικός του είναι ο έπαινος. Δίνει ζωή και προκαλεί θάνατο, και έχει εξουσία πάνω σε όλα τα πράγματα.", "Δέκα φορές μετά το Fajr (και το Maghrib), πριν απομακρυνθείτε από το καθιστικό ή την ομιλία σας.", "Δέκα καλές πράξεις, δέκα αμαρτίες διαγραμμένες, δέκα υψηλές τάξεις και προστασία από τον Σαϊτάν όλη την ημέρα."),
        "dua_la_hawla_kanz" to DuaText("Ένας θησαυρός της Τζάνα", "Δεν υπάρχει δύναμη και δύναμη εκτός από τον Αλλάχ.", "Συχνά, ανά πάσα στιγμή.", "Είναι ένας από τους θησαυρούς του Παραδείσου."),
        "dua_four_beloved_words" to DuaText("Οι τέσσερις πιο αγαπημένες λέξεις", "Δόξα στον Αλλάχ, όλος ο έπαινος είναι για τον Αλλάχ, κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, και ο Αλλάχ είναι ο Μεγαλύτερος.", "Τα πιο αγαπημένα λόγια στον Αλλάχ.", "Είναι πιο αγαπητοί στον Προφήτη ﷺ από όλα όσα ανατέλλει ο ήλιος."),
        "dua_two_light_words" to DuaText("Δύο Λέξεις Φως στη Γλώσσα", "Δόξα να είναι ο Αλλάχ και κάθε έπαινος είναι δικός του. δόξα στον Αλλάχ, τον Μεγαλοπρεπή.", "Ελαφριά στη γλώσσα, βαριά στη Ζυγαριά.", "Αγαπημένος στον Ελεήμονα, ελαφρύς στη γλώσσα και βαρύς στη Ζυγαριά. (Το τελευταίο χαντίθ του αλ-Μπουχάρι)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "Ω Κάτοχος Μεγαλειότητας και Τιμής!", "Κρατήστε το στη ντουά — την οδηγία του Προφήτη ﷺ.", "Ο Προφήτης ﷺ είπε: κρατήστε το «Ya Dhal-Jalali wal-Ikram»."),
        "dua_sleep_wadatu_janbi" to DuaText("Στο όνομά σου Ξάπλωσα", "Στο όνομά Σου, Κύριε μου, καταθέτω το πλευρό μου και στο όνομά Σου σηκώνομαι. Αν πάρεις την ψυχή μου, ελέησέ την και αν την ελευθερώσεις, προστάτευσέ την όπως προστατεύεις τους δίκαιους δούλους Σου.", "Αφού ξεσκονίσει το κρεβάτι και ξαπλώσει.", "Ανάθεση της ψυχής κάποιου στον Αλλάχ πριν από τον ύπνο."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Δημιούργησες την Ψυχή Μου", "Ω Αλλάχ, δημιούργησες την ψυχή μου και θα την πάρεις. Ο θάνατός του και η ζωή του ανήκουν σε Σένα. Αν το κρατήσεις ζωντανό, προστάτεψε το και αν το κάνεις να πεθάνει, συγχώρεσε το. Ω Αλλάχ, Σου ζητώ ευημερία.", "Πριν από τον ύπνο - αφηγείται ο Ibn Umar (RA).", "Ο Προφήτης ﷺ έδωσε εντολή να το πει αυτό πριν τον ύπνο."),
        "dua_sleep_atamana" to DuaText("Ευγνωμοσύνη πριν τον ύπνο", "Όλος ο έπαινος είναι για τον Αλλάχ που μας τάισε, μας έδωσε να πιούμε, μας αρκούσε και μας έδωσε καταφύγιο. Πόσοι είναι αυτοί που δεν έχουν κανέναν να τους αρκέσει ή να τους δώσει καταφύγιο.", "Όταν πηγαίνετε για ύπνο.", "Ο Προφήτης ﷺ το είπε αυτό όταν πήγαινε για ύπνο."),
        "dua_sleep_rabbas_samawat" to DuaText("Κύριος των Ουρανών — Πληρώστε το χρέος μας", "Ω Αλλάχ, Κύριε των ουρανών, της γης και του Πανίσχυρου Θρόνου, Κύριέ μας και Κύριο όλων των πραγμάτων, Σχιστή του σπόρου και της πέτρας της ημερομηνίας, Αποκαλυπτή της Τορά, του Ιντζίλ και του Φουρκάν! Αναζητώ καταφύγιο σε Σένα από το κακό όλων των οποίων το μπροστινό μέρος κρατάς. Ω Αλλάχ, εσύ είσαι ο Πρώτος, δεν υπάρχει τίποτα μπροστά σου. Είσαι ο Τελευταίος, δεν υπάρχει τίποτα μετά από Σένα. Είσαι ο Εκδηλωτικός, δεν υπάρχει τίποτα πάνω από Σένα. Εσύ είσαι ο Κρυφός, δεν υπάρχει τίποτα κρυφό από Σένα. Τακτοποιήστε το χρέος μας για εμάς και ελευθέρωσέ μας από τη φτώχεια.", "Πριν από τον ύπνο, ξαπλωμένος στη δεξιά πλευρά — διδάχθηκε στη Φατιμά (RA).", "Μια ντουέτα για την ανακούφιση από το χρέος και τις κακουχίες."),
        "dua_sleep_fear" to DuaText("Φόβος ή ανησυχία στον ύπνο", "Αναζητώ καταφύγιο στα τέλεια λόγια του Αλλάχ από τον θυμό Του και την τιμωρία Του, από το κακό των υπηρετών Του και από τους ψιθύρους των διαβόλων και από τον ερχομό τους σε μένα.", "Όταν αισθάνεστε φόβο ή ανησυχία στον ύπνο.", "Κάνοντας αυτό, αυτό το πράγμα δεν θα τον βλάψει."),
        "dua_waking_afani" to DuaText("Ξύπνημα: Αποκατέστησε την ψυχή μου", "Όλος ο έπαινος είναι για τον Αλλάχ που έδωσε στο σώμα μου ευεξία, μου επέστρεψε την ψυχή μου και μου επέτρεψε να Τον θυμάμαι.", "Στο ξύπνημα.", "Ευγνωμοσύνη για ένα νέο πρωινό."),
        "dua_allahu_rabbi" to DuaText("Αλλάχ, ο Αλλάχ είναι ο Κύριός μου", "Αλλάχ, ο Αλλάχ είναι ο Κύριός μου. Δεν συνδέω τίποτα μαζί Του.", "Σε θλίψη ή αγωνία — ο Προφήτης ﷺ το δίδαξε στον Asma bint Umays (RA).", "Κρατώντας το tawhid σε περιόδους στενοχώριας."),
        "dua_rahmataka_arju" to DuaText("Το Έλεος σου Ελπίζω", "Ω Αλλάχ, είναι το έλεός Σου στο οποίο ελπίζω, γι' αυτό μη με αφήσεις στον εαυτό μου ούτε μια ριπή οφθαλμού, και διορθώστε όλες τις υποθέσεις μου. Δεν υπάρχει θεός εκτός από Εσένα.", "Η ντουά αυτού που βρίσκεται σε στενοχώρια (Da'awat al-makrub).", "Ο Προφήτης ﷺ το ονόμασε ντουά εκείνου που βρίσκεται σε στενοχώρια."),
        "dua_against_enemy_ahzab" to DuaText("Εναντίον των Στρατιών του Εχθρού", "Ω Αλλάχ, Αποκαλυπτής του Βιβλίου, Γρήγορος στον λογαριασμό! Νίκησε τους συμμάχους. Ω Αλλάχ, νίκησέ τους και ταρακούνησε τους.", "Εναντίον του εχθρού - η ντουέτα της Μάχης των Συνομοσπονδιών.", "Η ντουέτα του Προφήτη ﷺ κατά του εχθρού."),
        "dua_anta_adudi" to DuaText("Είσαι το στήριγμά μου", "Ω Αλλάχ, είσαι το στήριγμα και ο βοηθός μου. Δι' Εσένα σχεδιάζω, δι' Εσένα προχωρώ και δι' Εσένα πολεμώ.", "Πριν από έναν διαγωνισμό ή μια μεγάλη πρόκληση.", "Ο Προφήτης ﷺ το είπε αυτό στη μάχη."),
        "dua_ikfinihim" to DuaText("Αρκετά Με Απέναντί τους", "Ω Αλλάχ, αρκέστε με εναντίον τους όπως θέλετε.", "Ενάντια στο κακό των καταπιεστών - η ντουέτα του αγοριού στην ιστορία των ανθρώπων της τάφρου.", "Ο Αλλάχ έσωσε το αγόρι από τους καταπιεστές."),
        "dua_qadarullah" to DuaText("Όταν συμβαίνει κάτι κακό", "Είναι το διάταγμα του Αλλάχ, και έκανε ό,τι ήθελε.", "Όταν συμβαίνει κάτι δυσάρεστο, αντί να πείτε «αν μόνο».", "Το «If only» ανοίγει την πόρτα στον Σαϊτάν."),
        "dua_ala_kulli_hal" to DuaText("Έπαινος σε κάθε κατάσταση", "Όλος ο έπαινος είναι για τον Αλλάχ σε κάθε περίπτωση.", "Όταν συμβαίνει κάτι αντιπαθητικό.", "Ο Προφήτης ﷺ το είπε αυτό όταν αντιμετώπισε κάτι που δεν του άρεσε."),
        "dua_dogs_barking" to DuaText("Ακούγοντας σκύλους να γαβγίζουν τη νύχτα", "Αναζητώ καταφύγιο στον Αλλάχ από τον Σαϊτάν, τον καταραμένο.", "Ακούγοντας σκύλους να γαβγίζουν ή ένα γαϊδουράκι να γαβγίζει τη νύχτα.", "Βλέπουν αυτό που δεν βλέπετε."),
        "dua_leaving_home_adilla" to DuaText("Καταφύγιο από την παραπλάνηση", "Ω Αλλάχ, καταφεύγω σε Σένα μήπως παραπλανηθώ ή παρασυρθώ, μήπως γλιστρήσω ή γλιστρήσω, μήπως κάνω λάθος ή αδικηθώ, μήπως συμπεριφέρομαι ανόητα ή με φέρονται ανόητα.", "Φεύγοντας από το σπίτι — αφήγηση από την Umm Salamah (RA).", "Ο Προφήτης ﷺ το απήγγειλε αυτό όποτε έφευγε από το σπίτι του."),
        "dua_ascending_descending" to DuaText("Ανεβαίνοντας και Κατεβαίνοντας", "Ο Αλλάχ είναι ο Μεγαλύτερος (όταν ανεβαίνει). — Δόξα στον Αλλάχ (όταν κατεβαίνει).", "Σε ένα ταξίδι, πείτε «Allahu Akbar» όταν ανεβαίνετε και «SubhanAllah» όταν κατεβαίνετε.", "Η πρακτική των Συντρόφων (RA) ταξιδεύοντας."),
        "dua_traveller_sahar" to DuaText("Δέηση του ταξιδιώτη πριν από την αυγή", "Ένας ακροατής άκουσε (και μεταβίβασε) τον έπαινο μας για τον Αλλάχ και τις καλές Του χάρη σε εμάς. Κύριε μας, συνόδευσέ μας και χάρισε την εύνοιά Σου πάνω μας — (το λέω αυτό) αναζητώντας καταφύγιο στον Αλλάχ από τη φωτιά.", "Σε ένα ταξίδι, πριν ξημερώσει.", "Ο Προφήτης ﷺ το είπε πριν ξημερώσει όταν ταξίδευε."),
        "dua_zawwadakallah" to DuaText("Προς τον ταξιδιώτη: Είθε ο Αλλάχ να παρέχει Taqwa", "Είθε ο Αλλάχ να σας παρέχει taqwa για το ταξίδι σας, να συγχωρήσει τις αμαρτίες σας και να σας κάνει το καλό όπου κι αν βρίσκεστε.", "Όταν αποχαιρετούν έναν ταξιδιώτη.", "Ο Προφήτης ﷺ έδωσε αυτή τη ντουά σε κάποιον που ξεκινούσε ένα ταξίδι."),
        "dua_traveller_to_resident" to DuaText("Ταξιδιώτης σε αυτούς που μένουν πίσω", "Σε εμπιστεύομαι στον Αλλάχ, στον οποίο οι εμπιστεύσεις δεν χάνονται ποτέ.", "Είπε ο ταξιδιώτης όταν αποχαιρετούσε την οικογένεια.", "Ανάθεση της ασφάλειας της οικογένειας στον Αλλάχ."),
        "dua_entering_village" to DuaText("Είσοδος σε πόλη ή χωριό", "Ω Αλλάχ, Κύριε των επτά ουρανών και όλων αυτών που σκιάζουν, Κύριε των επτά γης και όλων αυτών που φέρουν, Κύριε των διαβόλων και όλων αυτών που παραπλανούν, Κύριε των ανέμων και όλων αυτών που σκορπίζουν! Σου ζητάμε το καλό αυτής της πόλης και το καλό των κατοίκων της, και ζητάμε καταφύγιο σε Σένα από το κακό της, το κακό των κατοίκων της και το κακό όσων είναι μέσα της.", "Πριν μπείτε σε μια πόλη ή πόλη.", "Ο Προφήτης ﷺ το απήγγειλε αυτό όποτε ήθελε να μπει σε μια πόλη."),
        "dua_vehicle_stumbles" to DuaText("Όταν το όχημα σκοντάφτει", "Στο όνομα του Αλλάχ.", "Όταν το βουνό ή το όχημα γλιστρήσει ή σκοντάψει, αντί να πείτε «Μακάρι ο Σαϊτάν να χαθεί».", "Το να πεις Bismillah κάνει τον Σαϊτάν να συρρικνωθεί στο μέγεθος μιας μύγας."),
        "dua_ajz_kasal_haram" to DuaText("Καταφύγιο από την αδυναμία και τα γηρατειά", "Ω Αλλάχ, ζητώ καταφύγιο σε Σένα από την ανικανότητα και την τεμπελιά, από τη δειλία και τα γηρατειά, από τις δοκιμασίες της ζωής και του θανάτου και από την τιμωρία του τάφου.", "Μια περιεκτική καθημερινή προσφυγιά.", "Μια ντουέτα του Προφήτη ﷺ που γίνεται συχνά."),
    )
